function pickFields(jsonText, fields) {
  var data;
  try {
    data = JSON.parse(jsonText);
  } catch (e) {
    return null;
  }
  var out = {};
  for (var i = 0; i < fields.length; i++) {
    var key = fields[i];
    if (key in data) out[key] = data[key];
  }
  return out;
}

console.log(JSON.stringify(pickFields('{"a":1,"b":2,"c":3}', ['a', 'c'])));

