function makeAccount(balance) {
  var current = balance;
  return {
    deposit: function (n) {
      current = current + n;
      return current;
    },
    withdraw: function (n) {
      if (n > current) return -1;
      current = current - n;
      return current;
    },
    balance: function () {
      return current;
    }
  };
}

var acc = makeAccount(100);
console.log(acc.deposit(50));
console.log(acc.withdraw(30));

