function extractEmails(text) {
  var found = text.match(/[\w.]+@[\w.]+/g);
  return found === null ? [] : found;
}

function maskPhone(phone) {
  return phone.replace(/^(\d{3})\d{4}(\d{4})$/, '$1****$2');
}

